test:
records = {'Api.Example.': {'A': {'value': '192.0.2.7', 'ttl': 10}}}
cache = {}
first = resolve_dns(records, cache, 'API.EXAMPLE.', 'a', 100)
assert first == {'status': 'ok', 'value': '192.0.2.7', 'chain': ['api.example'], 'ttl_remaining': 10, 'from_cache': False}
assert cache == {('api.example', 'A'): {'value': '192.0.2.7', 'chain': ['api.example'], 'expires_at': 110}}
second = resolve_dns(records, cache, 'api.example', 'A', 107)
assert second == {'status': 'ok', 'value': '192.0.2.7', 'chain': ['api.example'], 'ttl_remaining': 3, 'from_cache': True}

records = {
    'api.example': {'CNAME': {'value': 'edge.example.', 'ttl': 8}},
    'edge.example': {'CNAME': {'value': 'origin.example', 'ttl': 5}},
    'origin.example': {'A': {'value': '198.51.100.4', 'ttl': 30}, 'TXT': {'value': 'healthy', 'ttl': 12}},
}
cache = {}
result = resolve_dns(records, cache, 'api.example.', 'A', 10)
assert result == {'status': 'ok', 'value': '198.51.100.4', 'chain': ['api.example', 'edge.example', 'origin.example'], 'ttl_remaining': 5, 'from_cache': False}
assert cache[('api.example', 'A')]['expires_at'] == 15
assert resolve_dns(records, cache, 'api.example', 'A', 15)['from_cache'] is False
assert resolve_dns(records, {}, 'origin.example', 'txt', 4)['value'] == 'healthy'

cache = {}
missing = resolve_dns({}, cache, 'missing.example', 'A', 0)
assert missing == {'status': 'not_found', 'value': None, 'chain': ['missing.example'], 'ttl_remaining': None, 'from_cache': False}
records = {
    'one.example': {'CNAME': {'value': 'two.example', 'ttl': 3}},
    'two.example': {'CNAME': {'value': 'one.example', 'ttl': 3}},
}
loop = resolve_dns(records, cache, 'one.example', 'A', 0)
assert loop == {'status': 'loop', 'value': None, 'chain': ['one.example', 'two.example', 'one.example'], 'ttl_remaining': None, 'from_cache': False}
assert cache == {}
